# ---- K-water 62~66쪽 서사 ----
def _tbl(heads, rows):
    out = []
    for i, (a, b, c) in enumerate(rows):
        bands = []
        if i == 0:
            bands.append(dict(k='cols', heads=heads, items=[a, b, c], w=[1.2, 1.8, 1.2], min=70))
        else:
            bands.append(dict(k='cols', items=[a, b, c], w=[1.2, 1.8, 1.2], min=70))
        out.append(dict(label=str(i + 1), bands=bands))
    return dict(t='ladder', rows=out)
